INSTANCE = 'i-t4n5tdhzaktd0x6tc34w'
REGION = 'ap-southeast-1'
async def run_shell(script, timeout=120):
    r = await call_cli(product='Ecs', action='RunCommand', version='2014-05-26', region=REGION, params={'RegionId': REGION, 'Type': 'RunShellScript', 'ContentEncoding': 'PlainText', 'CommandContent': script, 'Timeout': int(timeout), 'InstanceId': [INSTANCE]})
    invoke_id = r['InvokeId']
    for _ in range(60):
        await asyncio.sleep(3)
        d = await call_cli(product='Ecs', action='DescribeInvocationResults', version='2014-05-26', region=REGION, params={'RegionId': REGION, 'InvokeId': invoke_id, 'ContentEncoding': 'PlainText'})
        items = d.get('Invocation', {}).get('InvocationResults', {}).get('InvocationResult', [])
        if not items:
            continue
        item = items[0]
        st = item.get('InvocationStatus')
        if st in ('Success', 'Failed', 'PartialFailed', 'Stopped'):
            return {'status': st, 'output': (item.get('output') or item.get('Output') or '')[-4000:]}
    return {'status': 'Timeout'}
result = await run_shell("set -e\ncd /root/bluearmerp-v3\nmkdir -p api/internal/modules/manufacturing\nrm -f /tmp/_upload.b64\nprintf '%s' '' >> /tmp/_upload.b64\nbase64 -d /tmp/_upload.b64 > api/internal/modules/manufacturing/routes.go\nrm -f /tmp/_upload.b64\necho UPLOADED_routes.go", timeout=120)
